-- UhhhhhhReanim/Modules/biast.lua
-- AUTO-INSTALADOR: al cargarse, guarda solo las animaciones (.anim) y los sonidos (.mp3)
-- en UhhhhhhReanim/Content/Anims y UhhhhhhReanim/Content/Sounds (si no existen ya).
do
    local FILES = {
    { "UhhhhhhReanim/Content/Anims/onemoregame.anim", [==[]==] },
    { "UhhhhhhReanim/Content/Anims/TF2versionofonemoregame.anim", [==[]==] },
    { "UhhhhhhReanim/Content/Sounds/Startup1music_122815741276692.mp3", [==[]==] },
    { "UhhhhhhReanim/Content/Sounds/lemmeseeyalemme_118259277752742.mp3", [==[]==] },
    }

    local ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

    local function pureDecode(data)
        local lookup = {}
        for i = 1, 64 do lookup[ALPHABET:byte(i)] = i - 1 end
        data = data:gsub("[^%w%+/=]", "")
        local out, n = {}, 0
        for i = 1, #data, 4 do
            local a, b, c, d = data:byte(i, i + 3)
            local x = lookup[a] * 262144 + lookup[b] * 4096 + (lookup[c] or 0) * 64 + (lookup[d] or 0)
            local p1 = math.floor(x / 65536)
            local p2 = math.floor(x / 256) % 256
            local p3 = x % 256
            n += 1
            if c == 61 then
                out[n] = string.char(p1)
            elseif d == 61 then
                out[n] = string.char(p1, p2)
            else
                out[n] = string.char(p1, p2, p3)
            end
        end
        return table.concat(out)
    end

    local function decode(s)
        local ok, res = pcall(function() return crypt.base64decode(s) end)
        if ok and type(res) == "string" and #res > 0 then return res end
        ok, res = pcall(function() return base64decode(s) end)
        if ok and type(res) == "string" and #res > 0 then return res end
        ok, res = pcall(function() return base64_decode(s) end)
        if ok and type(res) == "string" and #res > 0 then return res end
        return pureDecode(s)
    end

    local function ensureFolder(path)
        local acc = ""
        for part in path:gmatch("[^/]+") do
            acc = acc == "" and part or (acc .. "/" .. part)
            if not isfolder(acc) then makefolder(acc) end
        end
    end

    local installed = 0
    for _, f in ipairs(FILES) do
        local path = f[1]
        local ok, err = pcall(function()
            if not isfile(path) then
                ensureFolder(path:match("^(.*)/[^/]+$"))
                writefile(path, decode(f[2]))
                installed += 1
            end
        end)
        if not ok then warn("[One More Game] No se pudo instalar " .. path .. ": " .. tostring(err)) end
    end
    if installed > 0 then
        print("[One More Game] Instalados " .. installed .. " archivos en UhhhhhhReanim/Content")
    end
end

local modules = {}
table.insert(modules, function()
    local m = {}
    m.ModuleType  = "DANCE"
    m.Name        = "One More Game"
    m.Description = "sl5✌️🫩 by Mrclown"
    m.Assets = {
        "onemoregame.anim",
        "Startup1music_122815741276692.mp3",
        "TF2versionofonemoregame.anim",
        "lemmeseeyalemme_118259277752742.mp3",
    }

    m.Config = function(parent)
        Util_CreateText(parent, "No settings.", 14, Enum.TextXAlignment.Center)
    end
    m.SaveConfig = function() return {} end
    m.LoadConfig  = function(save) end

    -- Duraciones (segundos)
    local FIRST_DURATION  = 21.08 -- primera animación (sin loop)
    local SECOND_DURATION = 10.03 -- música de la segunda (loop)

    -- false = efecto ORIGINAL: la minigun aparece/desaparece en los momentos de la 1ra
    --         animación (markers minigunspawn/nominigun) y se ve siempre en la 2da (TF2).
    -- true  = la minigun se ve todo el baile en tu mano.
    local ALWAYS_SHOW_MINI = false

    -- Minigun real (sacada del modelo "Mini" del juego)
    local MINI_MESH_ID    = "http://www.roblox.com/asset?id=71947307"
    local MINI_TEXTURE_ID = "http://www.roblox.com/asset?id=71947249"
    local MINI_SIZE  = Vector3.new(0.6218952, 5.2861128, 1.2437904)
    local MINI_SCALE = Vector3.new(1.5547394, 1.5547394, 1.5547394)
    local MINI_COLOR = Color3.fromRGB(27, 42, 53)
    -- Posición en la mano: es la misma que usa la animación original (pose "Mini" respecto al brazo derecho)
    local MINI_HAND_R6 = CFrame.new(
        -0.4072054, -3.0665924, -0.6729934,
         0.8097213,  0.0692132,  0.5827187,
        -0.2588225, -0.8490880,  0.4605003,
         0.5266521, -0.5236976, -0.6696106
    )
    -- R15: el centro del brazo R6 queda ~0.85 studs por encima del centro de la mano
    local MINI_HAND_R15 = CFrame.new(0, 0.85, 0) * MINI_HAND_R6

    ------------------------------------------------------------------
    -- MINIGUN (se crea con código, no hace falta ningún modelo)
    ------------------------------------------------------------------
    local players = game:GetService("Players")
    local keyframeSequenceProvider = game:GetService("KeyframeSequenceProvider")
    local LocalPlayer = players.LocalPlayer

    -- Cuándo se ve la minigun en la 1ra animación (segundos). Son todos los momentos en que el brazo
    -- derecho está en la pose de "sostener la minigun" (se repite varias veces durante el baile).
    local minigunWindows = {
        { 1.45, 2.77 },
        { 4.14, 5.48 },
        { 6.88, 8.02 },
        { 11.87, 13.02 },
        { 14.48, 15.78 },
        { 17.2, math.huge },
    }
    local introUnhideTime = 9.77
    local miniCreated = nil
    local effectToken = 0
    local hiddenState = {}
    local introDone   = {}
    local lockState   = nil

    local function weld(p0, p1, c0)
        local w = Instance.new("Weld")
        w.Part0 = p0
        w.Part1 = p1
        w.C0 = c0
        w.Parent = p1
    end

    local function createMinigun(figure)
        local existing = figure:FindFirstChild("Mini")
        if existing then
            existing:SetAttribute("OneMoreGameProp", true)
            return nil
        end
        local hand = figure:FindFirstChild("Right Arm")
        local offset = MINI_HAND_R6
        if not hand then
            hand = figure:FindFirstChild("RightHand")
            offset = MINI_HAND_R15
        end
        if not hand then
            hand = figure:FindFirstChild("Torso") or figure:FindFirstChild("UpperTorso")
            offset = CFrame.new(-0.2, -0.9, -1.4)
        end
        if not hand then return nil end

        local mini = Instance.new("Part")
        mini.Name = "Mini"
        mini.Size = MINI_SIZE
        mini.Color = MINI_COLOR
        mini.Material = Enum.Material.Plastic
        mini.CanCollide = false
        mini.CanTouch = false
        mini.CanQuery = false
        mini.Massless = true
        mini.Anchored = false
        mini.TopSurface = Enum.SurfaceType.Smooth
        mini.BottomSurface = Enum.SurfaceType.Smooth
        mini.Transparency = 1
        mini:SetAttribute("OneMoreGameProp", true)

        local mesh = Instance.new("SpecialMesh")
        mesh.MeshType = Enum.MeshType.FileMesh
        mesh.MeshId = MINI_MESH_ID
        mesh.TextureId = MINI_TEXTURE_ID
        mesh.Scale = MINI_SCALE
        mesh.Offset = Vector3.new(0, 0, 0)
        mesh.VertexColor = Vector3.new(1, 1, 1)
        mesh.Parent = mini

        weld(hand, mini, offset)
        mini.Parent = figure
        return mini
    end

    local function setMiniVisible(mini, visible)
        local tr = visible and 0 or 1
        if mini.Transparency ~= tr then
            mini.Transparency = tr
            for _, d in ipairs(mini:GetDescendants()) do
                if d:IsA("BasePart") then d.Transparency = tr end
            end
        end
    end

    ------------------------------------------------------------------
    -- Utilidades del efecto original (markers, ocultar intro)
    ------------------------------------------------------------------
    local function windowsFrom(markers, startName, endName)
        table.sort(markers, function(a, b) return a.t < b.t end)
        local out, open = {}, nil
        for _, v in ipairs(markers) do
            local n = v.name:lower()
            if n == startName and not open then
                open = v.t
            elseif n == endName and open then
                table.insert(out, { open, v.t })
                open = nil
            end
        end
        if open then table.insert(out, { open, math.huge }) end
        return out
    end

    local function readMarkers(id)
        local ok, result = pcall(function()
            return keyframeSequenceProvider:GetKeyframeSequenceAsync("rbxassetid://" .. id)
        end)
        if ok and result then
            local out = {}
            for _, kf in ipairs(result:GetKeyframes()) do
                for _, mk in ipairs(kf:GetMarkers()) do
                    table.insert(out, { name = mk.Name, t = kf.Time })
                end
            end
            return out
        end
        return nil
    end

    local function inWindows(list, t)
        for _, w in ipairs(list) do
            if t >= w[1] and t < w[2] then return true end
        end
        return false
    end

    local function applyHidden(model, hide)
        local st = hiddenState[model]
        if hide then
            if not st then
                st = { guis = {}, fx = {} }
                hiddenState[model] = st
            end
            for _, v in ipairs(model:GetDescendants()) do
                if v:IsA("BasePart") or v:IsA("Decal") then
                    v.LocalTransparencyModifier = 1
                elseif v:IsA("BillboardGui") then
                    if st.guis[v] == nil then st.guis[v] = v.Enabled end
                    v.Enabled = false
                elseif v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Beam") then
                    if st.fx[v] == nil then st.fx[v] = v.Enabled end
                    v.Enabled = false
                end
            end
            model:SetAttribute("PairHiddenLocal", true)
        elseif st then
            for _, v in ipairs(model:GetDescendants()) do
                if v:IsA("BasePart") or v:IsA("Decal") then
                    v.LocalTransparencyModifier = 0
                end
            end
            for k, v in pairs(st.guis) do if k.Parent then k.Enabled = v end end
            for k, v in pairs(st.fx)   do if k.Parent then k.Enabled = v end end
            hiddenState[model] = nil
            model:SetAttribute("PairHiddenLocal", nil)
        end
    end

    local function applyLock(hum, lock)
        if lock then
            if not lockState then
                lockState = {
                    h = hum, ws = hum.WalkSpeed, jh = hum.JumpHeight,
                    jp = hum.JumpPower, ar = hum.AutoRotate,
                }
            end
            hum.WalkSpeed = 0
            hum.JumpHeight = 0
            hum.JumpPower = 0
            hum.AutoRotate = false
        elseif lockState then
            local s = lockState
            lockState = nil
            if s.h.Parent then
                s.h.WalkSpeed = s.ws > 0 and s.ws or 16
                s.h.JumpHeight = s.jh
                s.h.JumpPower = s.jp
                s.h.AutoRotate = s.ar
            end
        end
    end

    -- firstT: tiempo de la 1ra animación (nil si no está activa)
    -- secondT: tiempo de la 2da animación (nil si no está activa)
    local function updateCharacter(character, isLocal, firstT, secondT)
        local humanoid = character:FindFirstChildOfClass("Humanoid")

        -- Minigun: 2da animación = siempre visible; 1ra = solo en sus ventanas
        local mini = character:FindFirstChild("Mini")
        if mini and mini:GetAttribute("OneMoreGameProp") then
            local visible = ALWAYS_SHOW_MINI or (secondT ~= nil) or (firstT ~= nil and inWindows(minigunWindows, firstT))
            setMiniVisible(mini, visible)
        end

        local hideNow = false
        if character:GetAttribute("PairIntroHidden") and not introDone[character] then
            if secondT == nil or secondT < introUnhideTime then
                hideNow = true
            else
                introDone[character] = true
            end
        end
        if hideNow or hiddenState[character] then
            applyHidden(character, hideNow)
        end
        if isLocal and humanoid then
            applyLock(humanoid, hideNow)
        end
    end

    ------------------------------------------------------------------
    -- Animaciones encadenadas
    ------------------------------------------------------------------
    local animator = nil
    local start    = 0
    local phase    = 1 -- 1 = primera (sin loop), 2 = segunda (loop)
    local introConn = nil

    local function StartFirst(figure)
        phase = 1
        SetOverrideDanceMusic(AssetGetContentId("Startup1music_122815741276692.mp3"), "One More Game", 0.8, NumberRange.new(0, FIRST_DURATION))
        start           = os.clock()
        animator        = AnimLib.Animator.new()
        animator.rig    = figure
        animator.track  = AnimLib.Track.fromfile(AssetGetPathFromFilename("onemoregame.anim"))
        animator.looped = false
        animator.speed  = 1
    end

    local function StartSecond(figure)
        phase = 2
        SetOverrideDanceMusic(AssetGetContentId("lemmeseeyalemme_118259277752742.mp3"), "TF2 version of One More Game", 0.8, NumberRange.new(0, SECOND_DURATION))
        start           = os.clock()
        animator        = AnimLib.Animator.new()
        animator.rig    = figure
        animator.track  = AnimLib.Track.fromfile(AssetGetPathFromFilename("TF2versionofonemoregame.anim"))
        animator.looped = true
        animator.speed  = 1
    end

    m.Init = function(figure)
        miniCreated = createMinigun(figure)

        effectToken += 1
        local token = effectToken
        task.spawn(function()
            local b = readMarkers("102683395987019")
            if token ~= effectToken then return end
            if b then
                for _, v in ipairs(b) do
                    if v.name:lower() == "enabled" then
                        introUnhideTime = v.t
                        break
                    end
                end
            end
        end)

        introConn = figure:GetAttributeChangedSignal("PairIntroHidden"):Connect(function()
            introDone[figure] = nil
        end)

        StartFirst(figure)
    end

    m.Update = function(dt, figure)
        local t = os.clock() - start
        if phase == 1 and t >= FIRST_DURATION then
            StartSecond(figure)
            t = 0
        end
        animator:Step(t)

        local isLocal = (figure == LocalPlayer.Character)
        updateCharacter(figure, isLocal, phase == 1 and t or nil, phase == 2 and t or nil)
    end

    m.Destroy = function(figure)
        effectToken += 1
        if introConn then introConn:Disconnect() introConn = nil end
        if miniCreated then miniCreated:Destroy() miniCreated = nil end
        if figure then
            applyHidden(figure, false)
            local hum = figure:FindFirstChildOfClass("Humanoid")
            if hum then applyLock(hum, false) end
            introDone[figure] = nil
        end
        animator = nil
    end
    return m
end)
return modules
